import json,re
from pathlib import Path
r=Path('artifacts');audit=json.loads((r/'airport-v2-asbuilt-audit.json').read_text(encoding='utf-8'));p=r/'auburn-airport-plan.html'
backup=r/'auburn-airport-plan-v2-planning.html'
if not backup.exists():backup.write_text(p.read_text(encoding='utf-8'),encoding='utf-8')
old=backup.read_text(encoding='utf-8');svg=re.search(r'<svg id="map".*?</svg>',old,re.S).group()
svg=re.sub(r'<polyline points="1200,1600.*?<circle cx="2500".*?/>','',svg)
svg=svg.replace('新建立交预留','高速立交已建').replace('y="1210"','y="1190"')
baseline=json.loads((r/'airport-relocation-baseline.json').read_text(encoding='utf-8'));oldroads={v['id'] for v in baseline['snapshot']['roads']}
def curve(v,color,width,dash=''):
 c=v['curve'];return f'<path d="M{c["a"]["x"]},{-c["a"]["z"]} C{c["b"]["x"]},{-c["b"]["z"]} {c["c"]["x"]},{-c["c"]["z"]} {c["d"]["x"]},{-c["d"]["z"]}" fill="none" stroke="{color}" stroke-width="{width}" {dash}/>'
overlay=''.join(curve(v,'#d47832',v.get('width_m',8)) for v in audit['snapshot']['roads'] if v['id'] not in oldroads)
utilityids=set(audit['operations']['water']['created_utility_edge_ids']+audit['operations']['power']['created_utility_edge_ids'])
overlay+=''.join(curve(v,'#078a9c',7,'stroke-dasharray="10 7"') for v in audit['snapshot']['utilities'] if v['id'] in utilityids)
svg=svg.replace('</svg>',overlay+'</svg>')
cost=audit['cost'];f=audit['raw']['components'];e=f['Game.Buildings.ElectricityConsumer']['fields'];w=f['Game.Buildings.WaterConsumer']['fields'];line=audit['airline'];passengers=sum(v.get('passenger_count',0) for v in line['vehicles'])
assert audit['checks']['road_binding'] and audit['checks']['four_directions']
assert e['m_FulfilledConsumption']==e['m_WantedConsumption']>0
assert w['m_FulfilledFresh']==w['m_FulfilledSewage']==w['m_WantedConsumption']>0
plan=json.loads((r/'auburn-airport-relocation-plan.json').read_text(encoding='utf-8'))
plan.update(status='built_and_operating',center=audit['airport']['position'],rotation_degrees=0,rotation_source='native_candidate',native_preview=True,facility_id=audit['airport']['facility_id'],road_edge_id=audit['airport']['road_edge_id'],asbuilt_audit='airport-v2-asbuilt-audit.json',cost=cost)
plan['actual_roads']=[v for v in audit['snapshot']['roads'] if v['id'] not in oldroads]
(r/'auburn-airport-relocation-plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2),encoding='utf-8')
page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>奥本山机场 · 竣工与运营</title><style>body{{margin:0;background:#eef2ed;color:#203e47;font:16px/1.7 system-ui}}main{{max-width:1200px;margin:auto;padding:32px}}section{{background:white;padding:24px;margin:24px 0;border-radius:14px}}h1{{font-size:36px;margin:10px 0}}svg{{width:100%;max-height:850px}}button{{padding:10px;margin:5px;background:#edf2ed;border:1px solid #bfd0ca;border-radius:7px}}td,th{{padding:12px;border-bottom:1px solid #ddd;text-align:left}}table{{width:100%;border-collapse:collapse}}a{{color:#126c82}}.note{{color:#66797d}}.stats{{display:flex;gap:20px;flex-wrap:wrap}}.stats b{{display:block;font-size:25px;color:#167569}}.stats div{{flex:1;min-width:180px}}small{{color:#4f7570}}</style><main><small>奥本山 / 新机场 V2 / 已建成并载客运行</small><h1>机场、公路接入与生命线已完成</h1><p>机场实建中心 <b>X=1700，Z=-1800.25，海拔544.01米</b>。跑道东西向、航站楼朝北，距规划时最近住宅边界约1.60公里。</p><section class="stats"><div><b>777,330</b>本次建设总费用</div><div><b>4 条匝道</b>高速两方向均可进出</div><div><b>100%</b>当前电力、供水与排污满足率</div><div><b>{line['vehicle_count']} 架 / {passengers} 人</b>回读飞机数 / 机上乘客</div></section><section id="map-section"><h2>竣工平面图</h2><button onclick="document.querySelector('#map').setAttribute('viewBox','-600 -200 4200 3200')">机场与旧城</button><button onclick="document.querySelector('#map').setAttribute('viewBox','2100 1150 850 700')">立交细节</button><button onclick="document.querySelector('#map').setAttribute('viewBox','-3500 -3500 11000 8000')">已购区域与原址</button>{svg}<p class="note">橙色为永久道路回读，蓝绿虚线为新建地下管线；红色为两端原生起降空域投影，黄线为敏感用地预留缓冲。桥头留在高压线南侧；东向下匝道接入站前连接路，避免与桥头重叠。</p></section><section id="checks"><h2>验收结果</h2><table><tr><th>项目</th><th>结果</th></tr><tr><td>机场与净空</td><td>Airport01 原生预览通过并完成永久建造；1136 × 376 米场地，东西起降空域各约1000 × 75米，保持预留</td></tr><tr><td>入口绑定</td><td>永久建筑 m_RoadEdge 已绑定普通四车道站前路</td></tr><tr><td>高速连接</td><td>跨线高架桥及四条单向匝道已建成；按永久节点和单行方向，西来、东来、西去、东去四项均可达</td></tr><tr><td>供电</td><td>{e['m_FulfilledConsumption']} / {e['m_WantedConsumption']}，已连接；数值为游戏原始消费单位</td></tr><tr><td>给排水</td><td>给水 {w['m_FulfilledFresh']} / {w['m_WantedConsumption']}；污水 {w['m_FulfilledSewage']} / {w['m_WantedConsumption']}；水污染 {w['m_Pollution']}</td></tr><tr><td>航空客运</td><td>“{line['name']}”已建成完整闭合线路，连接地图航空外部连接；{line['vehicle_count']}架飞机，回读机上{passengers}人、站点候车{line['total_waiting_passengers']}人</td></tr><tr><td>模拟速度</td><td>已恢复施工前最快速度</td></tr></table><p class="note">验收时间：{audit['captured']}。运营数值会继续变化；尚未跨完整高峰验证道路容量。近住宅的即时噪音包含既有城市噪音，不能将其全部归因于机场或据此保证长期零影响。</p></section><section><h2>费用与保留范围</h2><table><tr><td>机场</td><td>{cost['airport']:,}</td></tr><tr><td>站前路、桥与匝道</td><td>{cost['roads']:,}</td></tr><tr><td>地下给排水管</td><td>{cost['water']:,}</td></tr><tr><td>地下低压电缆</td><td>{cost['power']:,}</td></tr><tr><th>合计</th><th>{cost['total']:,}</th></tr></table><p>本次合计不含旧机场场址已建道路。原址道路与整地保持原状；本轮新机场完成客运配置，货运航站升级与货运航线未建设。机场两端净空及外围敏感用地缓冲继续保留。</p><a href="airport-v2-asbuilt-audit.json">永久对象、费用与验收数据</a> · <a href="auburn-airport-relocation-plan.json">更新后的坐标与实建道路</a> · <a href="auburn-airport-plan-v2-planning.html">施工前方案</a></section></main></html>'''
p.write_text(page,encoding='utf-8')
print(json.dumps({'page':str(p.resolve()),'cost':cost,'passengers':passengers},ensure_ascii=False))
